// Подготовка payload для Schedule триггера
return [{
  json: {
    chatId: parseInt($env.DEFAULT_CHAT_ID),
    triggerSource: 'schedule',
    timestamp: new Date().toISOString(),
    validated: true,
    skipRateLimit: true
  }
}];

// SECURITY: Validate webhook request
const chatId = $json.body?.chat_id;
const triggerSource = $json.body?.trigger_source || 'webhook';

// 1. Validate chat_id format
if (!chatId || !/^-?\d{7,13}$/.test(String(chatId))) {
  throw new Error('Invalid chat_id format');
}

// 2. Check whitelist
const allowedChatIds = ($env.ALLOWED_CHAT_IDS || '').split(',').map(id => id.trim());
if (!allowedChatIds.includes(String(chatId))) {
  throw new Error(`Unauthorized chat_id: ${chatId}`);
}

// 3. Sanitize input
const sanitizedChatId = parseInt(chatId);

if (isNaN(sanitizedChatId)) {
  throw new Error('Invalid chat_id: not a number');
}

// Pass validated data
return [{
  json: {
    chatId: sanitizedChatId,
    triggerSource: triggerSource,
    timestamp: new Date().toISOString(),
    validated: true,
    skipRateLimit: false
  }
}];

// Обрабатываем результаты Авито с санитизацией
const items = $input.all();
const results = [];

const sanitize = (text, maxLength = 200) => {
  if (!text) return '';
  return String(text)
    .replace(/[<>]/g, '')
    .replace(/[*_`\[\]]/g, '\\$&')
    .slice(0, maxLength)
    .trim();
};

for (const item of items) {
  const data = item.json;
  if (!data || !data.url) continue;

  // URL validation
  try {
    const url = new URL(data.url);
    if (!url.hostname.endsWith('avito.ru')) {
      console.warn('Suspicious URL:', data.url);
      continue;
    }
  } catch (e) {
    console.warn('Invalid URL:', data.url, e.message);
    continue;
  }

  results.push({
    json: {
      id: data.url,
      title: sanitize(data.title || 'Квартира', 150),
      price: sanitize(String(data.price || data.priceNum || 'Цена не указана'), 50),
      address: sanitize(data.address || data.location || 'Адрес не указан', 200),
      url: data.url,
      image: data.image || data.imageUrl || data.images?.[0] || null,
      source: 'Авито',
      city: 'Благовещенск',
      timestamp: new Date().toISOString()
    }
  });
}

console.log(`Авито: обработано ${results.length} из ${items.length}`);
return results.length > 0 ? results : [{ json: { empty: true, source: 'Авито' } }];

// Обрабатываем результаты ЦИАН с санитизацией
const items = $input.all();
const results = [];

const sanitize = (text, maxLength = 200) => {
  if (!text) return '';
  return String(text)
    .replace(/[<>]/g, '')
    .replace(/[*_`\[\]]/g, '\\$&')
    .slice(0, maxLength)
    .trim();
};

for (const item of items) {
  const data = item.json;
  if (!data) continue;

  const cianId = data.cianId || data.id;
  const url = data.siteUrl || data.url || (cianId ? `https://www.cian.ru/rent/flat/${cianId}/` : null);

  if (!url) continue;

  // URL validation
  try {
    const urlObj = new URL(url);
    if (!urlObj.hostname.endsWith('cian.ru')) {
      console.warn('Suspicious URL:', url);
      continue;
    }
  } catch (e) {
    console.warn('Invalid URL:', url, e.message);
    continue;
  }

  const address = data.formattedAddress || data.address || data.geo?.address || 'Адрес не указан';
  const price = data.formattedFullPrice || data.price || data.priceValue || 'Цена не указана';
  const image = data.mainImage?.full || data.image || data.photo || (data.photos && data.photos[0]) || null;

  results.push({
    json: {
      id: url,
      title: sanitize(data.title || 'Квартира', 150),
      price: sanitize(String(price), 50),
      address: sanitize(address, 200),
      url: url,
      image: image,
      source: 'ЦИАН',
      city: 'Благовещенск',
      timestamp: new Date().toISOString()
    }
  });
}

console.log(`ЦИАН: обработано ${results.length} из ${items.length}`);
return results.length > 0 ? results : [{ json: { empty: true, source: 'ЦИАН' } }];

// Финальная обработка и дедупликация
const items = $input.all();
const seen = new Set();
const results = [];
const stats = {
  total: items.length,
  duplicates: 0,
  noImage: 0,
  empty: 0,
  valid: 0
};

for (const item of items) {
  const data = item.json;

  // Skip empty markers
  if (data.empty) {
    stats.empty++;
    continue;
  }

  // Validate required fields
  if (!data.url && !data.id) {
    console.warn('Missing URL/ID:', data);
    continue;
  }

  // Deduplication
  const key = data.id || data.url;
  if (seen.has(key)) {
    stats.duplicates++;
    continue;
  }
  seen.add(key);

  // Filter out items without images
  if (!data.image) {
    stats.noImage++;
    continue;
  }

  stats.valid++;
  results.push({
    json: {
      id: data.id || data.url,
      title: data.title || 'Объявление',
      price: data.price || 'Цена не указана',
      address: data.address || 'Адрес не указан',
      url: data.url,
      image: data.image,
      source: data.source || 'Неизвестный',
      city: data.city || 'Благовещенск',
      timestamp: data.timestamp || new Date().toISOString()
    }
  });
}

console.log('📊 Статистика обработки:', JSON.stringify(stats, null, 2));

// Always return at least one item for stats tracking
if (results.length === 0) {
  return [{ json: { empty: true, stats } }];
}

// Add stats to first item
results[0].json.stats = stats;

return results;

// Batch Telegram Sender - отправка группами
const items = $input.all();
const BATCH_SIZE = 5; // Отправляем по 5 объявлений за раз
const messages = [];

// Remove stats object if present
const cleanItems = items.filter(item => !item.json.empty && item.json.url);

if (cleanItems.length === 0) {
  return [{ json: { skip: true, reason: 'No items to send' } }];
}

for (let i = 0; i < cleanItems.length; i += BATCH_SIZE) {
  const batch = cleanItems.slice(i, i + BATCH_SIZE);

  const text = batch.map(item => {
    const data = item.json;
    return `🏠 *${data.title}*\n📍 ${data.address}\n💰 ${data.price}\n🏢 ${data.source}\n\n[Открыть](${data.url})`;
  }).join('\n\n---\n\n');

  const batchNum = Math.floor(i / BATCH_SIZE) + 1;
  const totalBatches = Math.ceil(cleanItems.length / BATCH_SIZE);

  messages.push({
    json: {
      chatId: $('🔀 Merge Triggers').first().json.chatId,
      text: `📦 *Новые объявления* (${i + 1}-${Math.min(i + BATCH_SIZE, cleanItems.length)} из ${cleanItems.length}):\n\n${text}`,
      parse_mode: 'Markdown',
      disable_web_page_preview: false,
      batchInfo: `${batchNum}/${totalBatches}`
    }
  });
}

console.log(`📱 Подготовлено ${messages.length} Telegram сообщений для ${cleanItems.length} объявлений`);
return messages;

// Подготовка итогового сообщения со статистикой
const finalData = $('✅ Финал').first().json;
const stats = finalData.stats || {};

const chatId = $('🔀 Merge Triggers').first().json.chatId;
const triggerSource = $('🔀 Merge Triggers').first().json.triggerSource;

const duration = Date.now() - new Date($('🔀 Merge Triggers').first().json.timestamp).getTime();
const durationSeconds = Math.round(duration / 1000);

const text = `✅ *Парсинг завершен!*\n\n📊 *Статистика:*\n• Всего обработано: ${stats.total || 0}\n• Валидных: ${stats.valid || 0}\n• Дубликатов: ${stats.duplicates || 0}\n• Без фото: ${stats.noImage || 0}\n\n⏱ Время выполнения: ${durationSeconds}с\n🔄 Источник: ${triggerSource}\n⏰ Время: ${new Date().toLocaleString('ru-RU', { timeZone: 'Asia/Yakutsk' })}`;

return [{
  json: {
    chatId: chatId,
    text: text,
    parse_mode: 'Markdown'
  }
}];

