// Error Handler - обработка ошибок с уведомлением
const error = $input.first().json;
const errorMessage = error.message || error.error || 'Unknown error';
const errorContext = {
  workflow: $workflow.name,
  execution: $execution.id,
  timestamp: new Date().toISOString(),
  error: errorMessage,
  node: error.node || 'Unknown'
};

console.error('❌ Workflow Error:', JSON.stringify(errorContext, null, 2));

// Prepare error notification
const chatId = $env.DEFAULT_CHAT_ID;
const text = `❌ *Ошибка парсинга!*\n\n🔴 ${errorMessage}\n\n🕐 ${new Date().toLocaleString('ru-RU', { timeZone: 'Asia/Yakutsk' })}\n\n_Проверьте логи n8n для деталей_`;

return [{
  json: {
    chatId: parseInt(chatId),
    text: text,
    parse_mode: 'Markdown',
    errorContext: errorContext
  }
}];

// Monitoring & Metrics Collection
const executionStart = new Date($('🔀 Merge Triggers').first().json.timestamp).getTime();
const executionEnd = Date.now();
const duration = executionEnd - executionStart;

const finalStats = $('✅ Финал').first().json.stats || {};

const metrics = {
  workflow: {
    name: $workflow.name,
    executionId: $execution.id,
    mode: $execution.mode
  },
  timing: {
    start: new Date(executionStart).toISOString(),
    end: new Date(executionEnd).toISOString(),
    duration: duration,
    durationSeconds: Math.round(duration / 1000)
  },
  trigger: {
    source: $('🔀 Merge Triggers').first().json.triggerSource,
    chatId: $('🔀 Merge Triggers').first().json.chatId
  },
  results: {
    total: finalStats.total || 0,
    valid: finalStats.valid || 0,
    duplicates: finalStats.duplicates || 0,
    noImage: finalStats.noImage || 0,
    empty: finalStats.empty || 0
  },
  nodes: {
    avito: $('📥 Результаты Авито').all().length,
    cian: $('📥 Результаты ЦИАН').all().length,
    merged: $('📦 Объединить').all().length,
    final: $('✅ Финал').all().length
  },
  performance: {
    itemsPerSecond: finalStats.valid ? (finalStats.valid / (duration / 1000)).toFixed(2) : 0,
    successRate: finalStats.total ? ((finalStats.valid / finalStats.total) * 100).toFixed(2) + '%' : '0%'
  }
};

console.log('📈 Workflow Metrics:', JSON.stringify(metrics, null, 2));

return [{ json: metrics }];
